insert into public.tec_english_exercises(id, lesson_id, position, exercise_type, instruction, prompt, options, word_bank, left_items, right_items, audio_text, accepted_answers, answer_key, explanation, content_version, author, publication_status, review_status) values ('english-v1-u3-l4-e1', 'english-v1-u3-l4', 1, 'MULTIPLE_CHOICE', 'Escolha a frase em inglês com o mesmo significado.', 'Como dizer “Olá, meu nome é Lucas.” em inglês?', '["Hello, my name is Lucas.","Can I use your pencil?","The classroom is big."]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, null, '["Hello, my name is Lucas."]'::jsonb, '{"accepted":["Hello, my name is Lucas."]}'::jsonb, '“Hello, my name is Lucas.” significa “Olá, meu nome é Lucas.”.', 1, 'Equipe de conteúdo Tec Escola', 'STAGING', 'PEDAGOGICAL_REVIEW_PENDING') on conflict (id) do nothing;
insert into public.tec_english_exercises(id, lesson_id, position, exercise_type, instruction, prompt, options, word_bank, left_items, right_items, audio_text, accepted_answers, answer_key, explanation, content_version, author, publication_status, review_status) values ('english-v1-u3-l4-e2', 'english-v1-u3-l4', 2, 'WORD_ORDER', 'Toque nas palavras na ordem certa para montar a frase.', 'Monte: “Eu vou para a escola de manhã.”', '[]'::jsonb, '["morning.","the","in","school","to","go","I"]'::jsonb, '[]'::jsonb, '[]'::jsonb, null, '["I go to school in the morning."]'::jsonb, '{"accepted":["I go to school in the morning."]}'::jsonb, 'Em inglês, a ordem das palavras ajuda a mostrar quem faz a ação e o que acontece.', 1, 'Equipe de conteúdo Tec Escola', 'STAGING', 'PEDAGOGICAL_REVIEW_PENDING') on conflict (id) do nothing;
insert into public.tec_english_exercises(id, lesson_id, position, exercise_type, instruction, prompt, options, word_bank, left_items, right_items, audio_text, accepted_answers, answer_key, explanation, content_version, author, publication_status, review_status) values ('english-v1-u3-l4-e3', 'english-v1-u3-l4', 3, 'TRANSLATION', 'Escreva a tradução em inglês.', 'Minha irmã gosta de livros.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, null, '["My sister likes books."]'::jsonb, '{"accepted":["My sister likes books."]}'::jsonb, 'Uma forma correta de dizer isso é “My sister likes books.”.', 1, 'Equipe de conteúdo Tec Escola', 'STAGING', 'PEDAGOGICAL_REVIEW_PENDING') on conflict (id) do nothing;
insert into public.tec_english_exercises(id, lesson_id, position, exercise_type, instruction, prompt, options, word_bank, left_items, right_items, audio_text, accepted_answers, answer_key, explanation, content_version, author, publication_status, review_status) values ('english-v1-u3-l4-e4', 'english-v1-u3-l4', 4, 'LISTENING', 'Ouça e escreva em inglês a palavra ou expressão que escutou.', 'O que você ouviu?', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'sister', '["sister"]'::jsonb, '{"accepted":["sister"]}'::jsonb, 'Você ouviu “sister”, que significa “irmã”.', 1, 'Equipe de conteúdo Tec Escola', 'STAGING', 'PEDAGOGICAL_REVIEW_PENDING') on conflict (id) do nothing;
